<?php
if(!$PCC->tableExists('bans')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-gavel"></i><strong>Système de bannissement indisponible</strong><span>La table bans n’existe pas.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$state=strtolower((string)($_GET['state']??'active'));if(!in_array($state,array('active','all','expired'),true))$state='active';$where=array("bantype='user'");$types='';$params=array();if($state==='active')$where[]='expire>=?';elseif($state==='expired')$where[]='expire<?';if($state!=='all'){$types.='i';$params[]=time();}if($q!==''){$where[]='(value LIKE ? OR reason LIKE ? OR added_by LIKE ?)';$like='%'.mb_substr($q,0,64).'%';$types.='sss';$params[]=$like;$params[]=$like;$params[]=$like;}$rows=$DB->PreparedAll('SELECT * FROM bans WHERE '.implode(' AND ',$where).' ORDER BY expire DESC LIMIT 500',$types,$params);
?>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="sanctions"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Joueur, raison ou staff…"></div><div class="pcc-tabs"><?php foreach(array('active'=>'Actives','all'=>'Toutes','expired'=>'Expirées') as $k=>$label):?><a class="<?php echo $state===$k?'is-active':'';?>" href="<?php echo URL;?>/admin.php?<?php echo http_build_query(array('page'=>'sanctions','q'=>$q,'state'=>$k));?>"><?php echo $label;?></a><?php endforeach;?></div><button class="pcc-button secondary">Rechercher</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> sanction(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Joueur</th><th>Type</th><th>Raison</th><th>Staff</th><th>Début</th><th>Fin</th><th>Statut</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="pcc-empty compact"><strong>Aucune sanction trouvée</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):$user=$DB->PreparedRow('SELECT id,look FROM users WHERE username=? LIMIT 1','s',array($r['value']));$active=(int)($r['expire']??0)>=time();?><tr><td><?php if($user):?><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($user['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['value']);?></strong><small class="pcc-subline">#<?php echo (int)$user['id'];?></small></span></div><?php else:?><?php echo $h($r['value']);?><?php endif;?></td><td><?php echo $h($r['bantype']);?></td><td><?php echo $h($r['reason']);?></td><td><?php echo $h($r['added_by']??'—');?></td><td><?php echo !empty($r['added_date'])?$h($PCC->formatDate($r['added_date'])):'—';?></td><td><?php echo !empty($r['expire'])?$h($PCC->formatDate($r['expire'])):'—';?></td><td><span class="pcc-badge <?php echo $active?'danger':'';?>"><?php echo $active?'ACTIVE':'EXPIRÉE';?></span></td><td><?php if($user):?><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$user['id'];?>&tab=sanctions">Ouvrir</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="pcc-alert info"><i class="fas fa-info-circle"></i><div><strong>Scope sanction actuel confirmé</strong><p>Le core audité expose de façon fiable les bans utilisateur/IP. Warn, mute, kick et suspension ne sont pas présentés comme actifs tant qu’un backend autoritaire correspondant n’est pas identifié.</p></div></section>
